package co.za.millenniumsolutions.repository;
import co.za.millenniumsolutions.model.WorkEntry; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository;
@Repository public class WorkEntryRepository extends RepositorySupport { public WorkEntryRepository(JdbcTemplate j){super(j);} public WorkEntry save(WorkEntry x){update("INSERT INTO work_entry(id,user_id,work_period_id,activity_type_id,work_date,duration_minutes,status) VALUES (?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET status=excluded.status,duration_minutes=excluded.duration_minutes",x.id(),x.userId(),x.workPeriodId(),x.activityTypeId(),x.workDate().toString(),x.durationMinutes(),x.status()); return x;} }
